import{z as A,x as n,o as i,c as p,q as r,j as t,D as e,d as o,s as h,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Fish-Speech","description":"","frontmatter":{"title":"Fish-Speech","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fish-speech.md","filePath":"llm/fish-speech.md","lastUpdated":1791413859000}'),E={name:"llm/fish-speech.md"};function m(c,a,f,S,T,d){const s=n("Mermaid");return i(),p("div",null,[a[2]||(a[2]=r('<h1 id="fish-speech" tabindex="-1">Fish-Speech <a class="header-anchor" href="#fish-speech" aria-label="Permalink to &quot;Fish-Speech&quot;">​</a></h1><div class="epigraph"><p>我们用串行的快—慢双自回归结构稳定分组有限标量向量量化的序列生成，去掉 G2P，并在 72 万小时多语数据上训练。</p><footer>—— Liao et al., Fish-Speech: Leveraging Large Language Models for Advanced Multilingual Text-to-Speech Synthesis, arXiv:2411.01156</footer></div><p>Fish Audio 的 Fish-Speech（arXiv:2411.01156）把 TTS 写成：用语言模型直接吃文本，用 <strong>Dual-AR</strong>（慢 Transformer 管语义、快 Transformer 管码本）稳定 <strong>GFSQ</strong> 离散码，再用 Firefly-GAN（FFGAN）声码器出波。官方博客 <em>Introducing Fish-Speech</em> 与论文一致：SoTA 向的自回归多语 TTS、近 100% 码本利用率、面向实时 Agent，首包延迟约 150 ms。开源实现 <a href="https://github.com/fishaudio/fish-speech" target="_blank" rel="noreferrer">https://github.com/fishaudio/fish-speech</a> 。本篇写 1.4 技术报告这条线；后来的 Fish Audio S2（更大规模、RL、开源权重另一篇报告）只在边界里点名，不把 10M 小时与 4B Slow AR 写进 2411.01156 的方法学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VALL-E、FastSpeech、VITS 等多依赖 G2P。多音字、语码混合、缺乏词典的语言会把错误发音焊进前端，维护 \\(N\\) 套音素规则不可扩展。另一类系统把语义与声学拆开以提高稳，却削弱音色克隆对「这句话怎么说」的理解。扩散 / 流匹配 TTS 音质好，但多步 ODE 与首包延迟和 Agent 不对付。Fish-Speech 要的是：无 G2P 的多语、克隆稳、码本用满、消费卡上能实时。</p><p><span class="marginnote">G2P（grapheme-to-phoneme，字转音）是传统 TTS 前端把文字转成音素序列的一步，像「先查词典标好拼音再照着念」。去掉它，模型直接读文字，多音字靠上下文自己猜——和人一样，而不是靠维护一套套发音规则。</span></p><p>量化侧，普通 VQ 容易死码。FSQ 与成组量化（GVQ）被组合为 GFSQ，目标是压缩比与<strong>近 100% 码本利用率</strong>。利用率高不等于听感好，但利用率低时 AR 很难学到稳定的离散语言。</p><h3 id="双-ar-不是两套独立-tts" tabindex="-1">双 AR 不是两套独立 TTS <a class="header-anchor" href="#双-ar-不是两套独立-tts" aria-label="Permalink to &quot;双 AR 不是两套独立 TTS&quot;">​</a></h3><p>慢编码器式 Transformer 看文本，出隐状态与语义 token logits；快 Transformer 吃隐状态与码本嵌入的拼接，出码本 logits。二者串行：慢的每步为快的提供条件，快的在组内展开码本。这针对「GFSQ 多码并行时 AR 易崩」的稳定性，而不是把声学再交给扩散。论文把相对 DiT TTS 的效率写成优势：消费级 RTX 4060 移动约 1:5 RTF，RTX 4090 约 1:15，加 KV cache 后首包约 150 ms。</p><p><span class="marginnote">72 万小时是这篇报告的数据规模。社区站点 fish.audio 上的说话人库是产品层，不等于论文训练集可下载。FFGAN 基于 GFSQ，相对 HiFi-GAN 一类波形 GAN，多了离散码条件。</span></p><p><span class="marginnote">Dual-AR 可以类比乐队：慢模型是看谱的指挥，每一拍给出「这一拍是什么词、什么情绪」；快模型是乐手，在同一拍内把每个音符弹完。指挥不碰音符细节，乐手不管全曲结构——两个时间尺度各管各的，长序列反而不容易崩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>文本：LLM 式 tokenizer，无音素。慢 Transformer：\\(\\mathbf{h}=\\mathrm{SlowTransformer}(\\mathbf{x})\\)，\\(\\mathbf{z}=\\mathbf{W}_{\\mathrm{tok}}\\mathrm{Norm}(\\mathbf{h})\\)。快 Transformer：拼接 \\(\\tilde{\\mathbf{h}}=[\\mathbf{h};\\mathbf{c}]\\)，再 \\(\\mathbf{y}=\\mathbf{W}_{\\mathrm{cbk}}\\mathrm{Norm}(\\mathbf{h}^{\\mathrm{fast}})\\)。GFSQ 把潜条件编成组内 FSQ 码，FFGAN 解码为波形。训练目标是双轨交叉熵（语义 token 与码本），外加声码器的对抗与特征损失（论文以架构叙述为主，超参见代码）。多语、多情绪、克隆是同一套 AR，不另训语种专家。</p><p>慢、快两级在一个时间步之内怎么串行咬合，放大了一步来看：</p>',14)),(i(),t(l,null,{default:e(()=>[h(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E6%85%A2%20Transformer%20%E6%9C%AC%E6%AD%A5%E9%9A%90%E7%8A%B6%E6%80%81%20h%22%5D%20--%3E%20CT%5B%22%E4%BD%9C%E4%B8%BA%E6%9D%A1%E4%BB%B6%E5%96%82%E7%BB%99%E5%BF%AB%20Transformer%22%5D%0A%20%20CT%20--%3E%20F1%5B%22%E5%BF%AB%E6%A8%A1%E5%9E%8B%E5%9C%A8%E7%BB%84%E5%86%85%E9%80%90%E4%B8%AA%E5%87%BA%E7%A0%81%E6%9C%AC%E7%A0%81%22%5D%0A%20%20F1%20--%3E%20G%5B%22%E4%B8%80%E7%BB%84%20GFSQ%20%E7%A0%81%20%3D%20%E4%B8%80%E5%B8%A7%E5%A3%B0%E5%AD%A6%22%5D%0A%20%20G%20--%3E%20NEXT%5B%22%E6%9C%AC%E6%AD%A5%E5%AE%8C%E6%88%90%EF%BC%8C%E6%85%A2%E6%A8%A1%E5%9E%8B%E5%89%8D%E8%BF%9B%E5%88%B0%E4%B8%8B%E4%B8%80%E8%AF%AD%E4%B9%89%E6%AD%A5%22%5D%0A%20%20NEXT%20--%3E%7C%22%E5%BE%AA%E7%8E%AF%E8%87%B3%E6%96%87%E6%9C%AC%E7%BB%93%E6%9D%9F%22%7C%20H%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>推理：自回归出码，KV cache 加速慢/快两级。相对 Flow Matching，没有 NFE=10 的固定积分成本，延迟更可预测，但误差会沿时间累积——这是 AR TTS 的经典权衡。博客强调去掉扩散延迟。克隆通过参考音频编码进离散条件（实现细节以仓库当时模块为准），论文把它列为实验上相对基线更好的任务，不给「3 秒官方保证」——3 秒是 CosyVoice 报告的句子，不要混引。</p><h3 id="firefly-gan-要解决的是码本墙" tabindex="-1">Firefly-GAN 要解决的是码本墙 <a class="header-anchor" href="#firefly-gan-要解决的是码本墙" aria-label="Permalink to &quot;Firefly-GAN 要解决的是码本墙&quot;">​</a></h3><p>若量化器只用掉码本的一小角，AR 的 softmax 再尖也学不到其余符号。GFSQ 把 FSQ 的无死码倾向与分组结合起来，FFGAN 在高利用率码上做对抗重建。论文称评估达 100% 利用率。这是量化器指标，不是 MOS=人类。高频与气息依赖 GAN 判别器；若码率过低，GAN 会「编」出不存在的齿音。</p><p><span class="marginnote">码本利用率可以想成一本 1000 页的编码字典：若模型只用前 100 页，剩下 900 页就是「白背的死码」。利用率近 100% 意味着每页都被用过——AR 学的词汇表没有大片空白，声码器也才重建得出丰富的音色。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无 G2P 的机制是：多音字的读音由上下文 token 决定，与 LLM 消歧是同一现象。代价是需要足够多的「同字不同音」上下文，72 万小时提供统计，不提供可审计词典。Dual-AR 把「句子级语言结构」和「帧级声学码」分成两个时间尺度，避免单一深层 AR 在长码本序列上的稳定性崩溃，也避免把全部声学细节压进慢模型的隐维。</p><p>与 CosyVoice 2 对照：Fish 没有独立流匹配 Mel 解码器，音色与细节更多走 GAN；CosyVoice 用监督 ASR token + OT 流。Fish 的 150 ms 与 CosyVoice 2 的 150 ms 数字相同量级，测试栈不同。Fish 论文明确点名 CosyVoice、Matcha-TTS 等为相关工作，定位自己为 Dual-AR + GFSQ，而不是混合 LM-CFM。</p><p><span class="marginnote">官方样本页与 fish.audio 在线合成是听感来源。论文没有把「超越所有闭源」写成主表标题；写进文章需带「作者自称 / 博客 SoTA」。加速数字绑定 4060 mobile 与 4090，换批大小与量化会变。</span></p><h3 id="agent-就绪是延迟曲线-不是对话模型" tabindex="-1">Agent 就绪是延迟曲线，不是对话模型 <a class="header-anchor" href="#agent-就绪是延迟曲线-不是对话模型" aria-label="Permalink to &quot;Agent 就绪是延迟曲线，不是对话模型&quot;">​</a></h3><p>「面向 AI 交互」指首包与 RTF，不是 Fish-Speech 自带 ASR 与对话策略。真正的 voice agent 仍要外接识别与 LLM。仓库若提供实时流式接口，那是工程封装。多情绪依赖训练分布与提示；没有像 CosyVoice 2 那样把「指令文本与零样本合并」写成同一套正式协议——Fish 博客更强调架构与码本。</p>',10)),(i(),t(l,null,{default:e(()=>[h(s,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E6%97%A0%20G2P%22%5D%20--%3E%20SLOW%5B%22Slow%20Transformer%20%E8%AF%AD%E4%B9%89%22%5D%0A%20%20SLOW%20--%3E%20FAST%5B%22Fast%20Transformer%20%E7%A0%81%E6%9C%AC%22%5D%0A%20%20GFSQ%5B%22GFSQ%20%E7%A6%BB%E6%95%A3%E7%A0%81%22%5D%20--%3E%20FAST%0A%20%20FAST%20--%3E%20FFGAN%5B%22Firefly-GAN%20%E5%A3%B0%E7%A0%81%E5%99%A8%22%5D%0A%20%20FFGAN%20--%3E%20WAV%5B%22%E6%B3%A2%E5%BD%A2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>论文把相关工作写成一条谱系：VALL-E 式 codec LM、VITS / FastSpeech 式声学模型、YourTTS 式克隆、以及 CosyVoice / Matcha-TTS 一流匹配。Fish-Speech 的差分是 Dual-AR 稳住 GFSQ，而不是再叠一条 Mel 扩散。评测叙述强调复杂语言现象与克隆相对基线更好；具体 MOS、WER 表以 PDF 实验节为准，博客的 SoTA 句不能替代表格。在线 playground 的社区音色是用户上传与授权问题，和论文训练集不是同一法律对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>AR 错误累积、句中崩溃、语码混合仍难。GAN 声码器在未见过的采样率或频响上会失真。无 G2P 不自动等于专有名词可读，仍可能要用户注音。开源许可与商用条款以 GitHub / 卡片为准。S2 Pro（后续技术报告 arXiv:2603.08823 一线）改数据规模与 RL，架构仍 Dual-AR，但不是本篇的 72 万小时模型。实时因子随量化、batch 与流式切块变化：论文的 4060 / 4090 数字只说明「可以不用 ODE 多步也能到交互延迟」，不能写成所有部署的 SLA。</p><p>不要把 EVA-GAN 论文（同一作者相关声码器工作）的 CAM 模块未经引用就画进 FFGAN。不要用第三方「最强开源 TTS」榜单代替 2411.01156。与 Whisper 无直接互逆关系。</p><p><span class="marginnote">出处：Shijia Liao et al.，<em>Fish-Speech: Leveraging Large Language Models for Advanced Multilingual Text-to-Speech Synthesis</em>，arXiv:2411.01156。博客 <a href="https://fish.audio/blog/introducing-fish-speech/" target="_blank" rel="noreferrer">https://fish.audio/blog/introducing-fish-speech/</a> 。代码 <a href="https://github.com/fishaudio/fish-speech%E3%80%82" target="_blank" rel="noreferrer">https://github.com/fishaudio/fish-speech。</a></span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Fish-Speech 是无 G2P 的多语自回归 TTS：Slow/Fast Dual-AR + GFSQ + Firefly-GAN。</li><li>训练数据 72 万小时；官方称码本利用率近 100%，首包约 150 ms。</li><li>4060 mobile / 4090 上 RTF 约 1:5 / 1:15（论文环境）。</li><li>相对扩散 TTS，用 AR+GAN 换可预测延迟；相对 CosyVoice，不用流匹配 Mel。</li><li>后续 S2 系列是另一规模点，不改变本篇方法学引用。</li><li>出处：arXiv:2411.01156 与 Fish Audio 官方博客。</li></ul>',7))])}const B=A(E,[["render",m]]);export{u as __pageData,B as default};
